\label{definition:gasket}
A set $K\subset \widehat\mathbb{C} $ is a \textit{gasket} if it is a locally connected continuum with empty interior that has the following properties. 
\begin{enumerate}
    \item Each complementary component of $K$ is a Jordan region.
    \item The boundaries of any two complementary components of $K$ share at most one point, called a \textit{contact point}.
    \item No point of $\widehat\mathbb{C}$ belongs to the boundaries of three complementary components of $K$.
    \item The \textit{contact graph} corresponding to $K$, obtained by assigning a vertex to each complementary component and an edge if two components share a boundary point, is connected.
\end{enumerate}

\label{conj:gqh}
Let $\mathcal J$ be the Julia set of a rational map and $\Lambda$ be the limit set of a Kleinian group.
Suppose that $\mathcal J$ and $\Lambda$ are connected and not homeomorphic to the circle or the $2$-sphere. Then there exists no quasiconformal homeomorphism of the Riemann sphere that maps $\mathcal J$ onto $\Lambda$.

\label{lemma:qs_glue}
    Let $f\colon [-1,1]\to \mathbb{R}$ be a homeomorphic embedding such that $f|_{[-1,0]}$ and $f|_{[1,0]}$ are quasisymmetric and there exists $\lambda\geq 1$ with the property that
    \begin{align}\label{lemma:qs_glue_ineq}
        \lambda^{-1} |t|\leq  |f(t)-f(0)|\leq \lambda |t|
    \end{align}
    for all $t\in [-1,1]$. Then $f$ is quasisymmetric.

\label{proposition:quasidisk}
    Let $U\subset \mathbb{C}$ be a quasidisk and $f\colon \overline U\to \mathbb{R}$ be a continuous function such that $f\in W^{1,1}(U)$. Then for a.e.\ line $L$ parallel to a coordinate direction we have
$$\mathcal H^1(f(\partial U\cap E))=0.$$

\label{lemma:qn}
    Let $\Omega_n=\mathbb{C} \setminus  [n,\infty)$ and $q_n\in \Omega_n$, $n\in \mathbb{N}\cup \{0\}$. Suppose that there exist constants $C>0$ and $\delta\in (0,1)$ such that $$d_{\Omega_n}(q_{n-1},q_n)< C \delta^n$$
    for each $n\in \mathbb{N}$. Then the sequence $\{q_n\}_{n\in \mathbb{N}}$ is convergent in the Euclidean metric and, in particular, it is bounded.

\label{definition:markov_partition}
A \textit{Markov partition} associated to a covering map $f\colon \mathbb{S}^1\to \mathbb{S}^1$ is a covering of the unit circle by closed arcs $A_k=\mathpalette 
  \sbox0{$\m@th[a_k, a_{k+1}]$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
, $k\in \{0,\dots, r\}$, $r\geq 1$, where $a_{r+1}=a_0$, that have disjoint interiors and satisfy the following conditions.
\begin{enumerate}[label={(\roman*)}]
\item\label{markov:i} The map $f_k=f|_{\operatorname{int}{A_k}}$ is injective for $k\in \{0,\dots,r\}$.
\item\label{markov:ii} If $f(\operatorname{int}{A_k})\cap \operatorname{int}{A_j}\neq \emptyset$ for some $k,j\in \{0,\dots,r\}$, then $\operatorname{int}{A_j}\subset f(\operatorname{int}{A_k})$. 
\item\label{markov:iii} The set $\{a_0,\dots,a_r\}$ is invariant under $f$.
\end{enumerate}    
We denote the above Markov partition by $\mathcal P(f;\{a_0,\dots,a_r\})$.

\label{definition:hyperbolic}
Let $a \in\{a_0,\dots,a_r\}$. We say that $a^+$ (resp.\ $a^-$) is \textit{hyperbolic} if there exist $\lambda>1$ and $L\geq 1$ such that the following statement is true. 

\smallskip
\noindent
If $I_1,I_2$ are adjacent complementary arcs of $F_n$, $n\geq 1$, $a$ is an endpoint of $I_1$, and $I_1,I_2\subset \mathpalette 
  \sbox0{$\m@th[a,z_0]$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
 (resp.\ $I_1,I_2\subset \mathpalette 
  \sbox0{$\m@th[z_0,a]$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
) for some $z_0\neq a$, then for $i\in \{1,2\}$ we have
\begin{align}\label{inequality:adjacenthyperbolic}
L^{-1}\lambda^{-n}&\leq \operatorname{diam} {I_i} \leq L\lambda^{-n}.
\end{align}
In that case we set $\lambda(a^+)=\lambda$ (resp.\ $\lambda(a^-)=\lambda$) and call this number the \textit{multiplier} of $a^+$ (resp.\ $a^-$).

\label{definition:parabolic}
Let $a \in\{a_0,\dots,a_r\}$. We say that $a^+$  (resp.\ $a^-$) is \textit{parabolic} if there exist $N\in \mathbb{N}$ and $L\geq 1$ such that the following statement is true.

\smallskip
\noindent
If $I_1,I_2$ are adjacent complementary arcs of $F_n$, $n\geq 1$, $a$ is an endpoint of $I_1$, and $I_1,I_2\subset \mathpalette 
  \sbox0{$\m@th[a,z_0]$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
 (resp.\ $I_1,I_2\subset \mathpalette 
  \sbox0{$\m@th[z_0,a]$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
) for some $z_0\neq a$, then we have
\begin{align}\label{inequality:parabolic_1}
\frac{L^{-1}}{n^{1/N}}&\leq \operatorname{diam} {I_1} \leq \frac{L}{n^{1/N}} \quad \textrm{and}\quad \frac{L^{-1}}{n^{1/N +1}}\leq \operatorname{diam} {I_2} \leq \frac{L}{n^{1/N +1}}.
\end{align}
In that case we set $N(a^+)=N$ (resp.\ $N(a^-)=N$) and call the number $N(a^+)+1$ (resp.\ $N(a^-)+1$) the \textit{multiplicity} of $a^+$ (resp.\ $a^-$).

\label{defn:cyl}
Let $\mathcal{R}=\{P_i\}_{i=1}^k$ be a finite subdivision rule. 
\begin{itemize}
    \item We say that $\mathcal R$ is \textit{simple} if, for each $i\in \{1,\dots,k\}$, $\mathcal{G}(P_i)$ is a simple graph, i.e., no pair of vertices is connected by multiple edges and no edge connects a vertex to itself.
    \item We say that $\mathcal R$ is \textit{irreducible} if, for each $i\in \{1,\dots,k\}$, $\partial P_i$ is an induced subgraph of $\mathcal{G}(P_i)$, i.e., $\partial P_i$ contains all edges of $\mathcal{G}(P_i)$ that connect vertices in $\partial P_i$.
    \item We say that $\mathcal R$ is \textit{acylindrical} if, for each $i\in \{1,\dots,k\}$, for any pair of non-adjacent vertices $v,w \in \partial P_i$, the two components of $\partial P_i \setminus \{v,w\}$ are connected in $\mathcal{G}(P_i) \setminus \{v, w\}$.
    We call $\mathcal R$ \textit{cylindrical} otherwise.
\end{itemize}

\label{theorem:qc_david_gasket}
    Let $J\subset \widehat\mathbb{C}$ be a gasket whose contact graph is a spherical subdivision graph for a simple, irreducible, acylindrical finite subdivision rule. Let $f\colon \widehat \mathbb{C}\to \widehat \mathbb{C}$ be a homeomorphism. Suppose that the components of $\widehat \mathbb{C}\setminus J$ and $\widehat \mathbb{C}\setminus f(J)$ are uniform quasidisks.       
    \begin{enumerate}[label=\normalfont(\arabic*)]
        \item If $f$ is quasiconformal on $\widehat\mathbb{C}\setminus J$, then $f$ is quasiconformal on $\widehat\mathbb{C}$.
        \item If $f$ is a David map on $\widehat\mathbb{C}\setminus J$, then $f$ is a David map on $\widehat\mathbb{C}$.
    \end{enumerate}

Let $\mathcal{R}$ be a finite subdivision rule and $\mathcal P$ be a circle packing.
    \begin{itemize}
        \item We say that $\mathcal P$ is a circle packing with finite subdivision rule of $\mathcal{R}$ if its tangency graph is a subdivision graph for $\mathcal{R}$.
        \item We say that $\mathcal P$ is a circle packing with spherical subdivision rule of $\mathcal{R}$ if its tangency graph is a spherical subdivision graph for $\mathcal{R}$.
    \end{itemize}

\label{defn:pf}
    Suppose that the sequence $\{F^n\}_{n\geq 0}$ is periodic with period $p$.
We say that $\{F^n\}_{n\geq 0}$ is \textit{hyperbolic} if $\partial F^{p} \cap \partial F^0$ is either empty or a single vertex. Otherwise, we say that $\{F^n\}_{n\geq 0}$ is \textit{parabolic}.

Let $\mathcal{P}, \mathcal{P}' \in \mathcal{M}(\mathcal{G})$.  A quasiconformal homeomorphism $\Psi: \widehat \mathbb{C} \to \widehat \mathbb{C}$ between $\mathcal{P}$ and $\mathcal{P}'$ is said to be a \textit{Teichm\"uller mapping} if for every $n\geq 0$ and for every non-external face $F$ of $\mathcal{G}^n$ we have
\begin{itemize}
    \item $\frac{1}{2} \log K(\Psi|_{\Omega_{F}}) = d(\mathcal{P}_{F}, \mathcal{P}'_{F})$ and
    \item $\Psi|_{\Lambda_{F}}$ conjugates the dynamics of $\Gamma_{F}$ and $\Gamma'_{F}$.
\end{itemize}

Suppose that $\Psi$ is induced by a subdivision homomorphism $\psi\colon \mathcal G^1\to \mathcal G^0$. Let $C=C_v$. By Proposition \ref{prop:induceMarkovMap} \ref{ma:3}, $\psi(v)=v$ and $\Psi|_{C}$ is a covering map from $C$ onto itself. For $i\in \{0,\dots,r\}$ let $F_i$ be the face of $\mathcal G^1$ that contains the edges $[v,u_i]$ and $[v,u_{i+1}]$ in its $1$-skeleton, where $u_{r+1}\coloneqq u_0$; if $i=1$, there are only two faces. By condition \ref{condition:siG}, the faces $F_0,\dots,F_r$ are distinct.  For each face $F_i$ the face $\psi_*(F_i)$ of $\mathcal G^0$ contains the vertex $v$ in its $1$-skeleton and contains some of the faces $F_j$, $j\in \{0,\dots,r\}$, of $\mathcal G^1$. The $1$-skeleton of $\psi_*(F_i)$ contains the edges $[v,\psi(u_i)]$ and $[v,\psi(u_{i+1})]$, where $\psi(u_i),\psi(u_{i+1})\in \{u_0,\dots,u_r\}$ since $\mathcal G^0\subset \mathcal G^1$.

    We define $U_{i}=\Omega_{F_i}$ for $i\in \{0,\dots,r\}$. Each level $1$ tile $U_i$ is mapped by $\Psi$ homeomorphically to the level $0$ tile $\Omega_{\psi_*(F_i)}$ by Proposition \ref{prop:induceMarkovMap} \ref{ma:1}. We denote by $V_0,\dots,V_l$ the list of level $0$ tiles arising in this way; see Figure \ref{fig:tileC}. Note that the open tiles $V_0,\dots,V_l$ are pairwise disjoint and the open tiles $U_0,\dots,U_r$ are also pairwise disjoint (by Lemma \ref{lem:intersectionBoundary} \ref{lem:boundary:5}). Also, $\partial U_i\cap C=\{a_i,a_{i+1}\}$ (by Lemma \ref{lem:intersectionBoundary} \ref{lem:boundary:7}), where $a_{r+1}\coloneqq a_0$. By Proposition \ref{prop:induceMarkovMap} \ref{ma:4}, $\Psi$ maps $a_i$ to the point $C\cap C_{\psi(u_i)}$ which is contained in $\{a_0,\dots,a_r\}$. Therefore, $\Psi$ is injective in each arc $\mathpalette 
  \sbox0{$\m@th(a_i,a_{i+1})$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
 and leaves the set $\{a_0,\dots,a_r\}$ invariant. This implies that the set $\{a_0,\dots,a_r\}$ gives a Markov partition for $\Psi|_{C}$; see Definition \ref{definition:markov_partition}. The preimages of each arc $\mathpalette 
  \sbox0{$\m@th(a_i,a_{i+1})$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
 under $(\Psi|_C)^{\circ n}$ are arcs, each of which is contained in open tiles of level $n$, where $n\in \mathbb{N}$, as a consequence of Proposition \ref{prop:induceMarkovMap} \ref{ma:11}. By Proposition \ref{prop:diam->0} and property \ref{expansive:diameters}, $\Psi$ is expansive on $C$. We have verified \ref{cmc:1}.

    Now, we verify \ref{cmc:2}. As discussed, each open tile $U_i$ is mapped by $\Psi$ homeomorphically to a level $0$ tile. Moreover, if an open tile $U_i$ intersects an open tile $V_k$, then $U_i\subset V_k$; see Lemma \ref{lem:intersectionBoundary} \ref{lem:boundary:5} and  \ref{lem:boundary:6}. Since $V_k\subset \mathbb{C}$ for each $k\in \{0,\dots,r\}$, we have verified condition \ref{condition:uv}. Conditions \ref{condition:qs} and  \ref{condition:qs_strong} follow immediately from Proposition \ref{prop:qce}.

\label{lemma:tangent_repelling}
    Let $R$ be a rational map such that two fixed Fatou components $U,V$ are Jordan regions whose boundaries intersect at a repelling fixed point $z_0$. 
    \begin{enumerate}[label=\normalfont(\arabic*)]
        \item\label{lemma:tangent_repelling:1} If $U$ and $V$ are tangent to each other at $z_0$, then $\mathcal{J}(R)$ is a Jordan curve and in particular it is not a gasket.
        \item\label{lemma:tangent_repelling:2} There exists no quasiconformal homeomorphism of the sphere that maps $U$ and $V$ to two disks that are tangent to each other.
    \end{enumerate}

Since $R$ has no critical points on the Julia set, it is a covering map from $\partial W_v$ onto itself.  By Proposition \ref{prop:subdivision_g} \ref{sg:3}, $R$ induces a subdivision homomorphism between $\mathcal G^1$ and $\mathcal G^0$. This implies that the set $\{a_0,\dots,a_r\}$ gives a Markov partition for $R|_{\partial W_v}$ (see also the proof of Theorem \ref{thm:cmc} \ref{cmc:2}). Consider the preimages under $R^{\circ n}$ of the arcs $A_k=\mathpalette 
  \sbox0{$\m@th[a_k,a_{k+1}]$$} 
  \vbox{
    \hbox{\resizebox{\wd0}{\height}{{\usefont{U}{tipa}{m}{n}\symbol{62}}}}
    \nointerlineskip
    \box0
  } 
. Each preimage is contained in the boundary of $W(\operatorname{int} F^n)$ for some face $F^n$ of $\mathcal G^n$ (recall the notation from Section \ref{section:gasket_subdivision}). Lemma \ref{lemma:gasket_sub} \ref{gs:0} implies that the diameters of those sets converge to $0$. In combination with \ref{expansive:diameters}, we see that $R|_{\partial W_v}$ is expansive.  By Theorem \ref{thm:cmc}, $\Psi|_{\partial D_v}$ is an expansive covering map and the set $\{b_0,\dots,b_r\}$ defines a Markov partition for $\Psi|_{\partial D_v}$.

    Consider the map $h_v\colon \{a_0,\dots,a_r\}\to \{b_0,\dots,b_r\}$ defined by $h_v(a_i)=b_i$, $i\in \{0,\dots,r\}$. By Proposition \ref{prop:induceMarkovMap} \ref{ma:4} and Proposition \ref{prop:subdivision_g} \ref{sg:3}, we see that $h_v$ conjugates $R$ to $\Psi$ on $\{a_0,\dots,a_r\}$. The expansivity of the maps implies that $h_v$ extends to a topological conjugacy between $R|_{\partial W_v}$ and $\Psi|_{\partial D_v}$ (see \cite{LN24}*{Lemma 3.4} or \cite{CovenReddy:expansive}*{Property $(2')$, p.~99}). We have therefore proved  \ref{f:1}, \ref{f:2}, and \ref{f:3}.

    Suppose that $W_v$ is a quasidisk, as in \ref{f:4}. Let $\phi_v\colon W_v \to \mathbb{D}$ be a conformal map that extends homeomorphically to the closures so that $B_v\coloneqq \phi_v \circ R \circ \phi_v^{-1}\colon  \overline \mathbb{D} \to \overline \mathbb{D}$ is a Blaschke product of degree $d=d_v$. Let $\{\widetilde{a_0},\dots, \widetilde{a_r}\} = \phi_v(\{a_0, \dots, a_r\})$ be the corresponding Markov partition of $B_v$ in $\mathbb S^1$. Since $W_v$ is a quasidisk, $\partial W_v$ contains no parabolic point of multiplicity $2$ (otherwise, $\partial W_v$ would contain a cusp).  We claim that $\{\widetilde{a_0},\dots, \widetilde{a_r}\}$ contains the parabolic fixed point of $B_v$ on $\mathbb S^1$, if there exists one. Suppose  that $\widetilde{a}$ is the parabolic fixed point of $B_v$ in $\partial \mathbb S^1$, so it attracts orbits of $\mathbb{D}$. Then $\widetilde{a}$ corresponds to a parabolic point $\phi_v^{-1}(\widetilde{a})$ in $\partial W_v$ that has multiplicity $3$ by Lemma \ref{lem:pt}. So it is a contact point between $W_v$ and another fixed Fatou component $W_u$ (recall that every periodic Fatou component of $R$ is fixed). Note that $[v,u]$ must be an edge of $\mathcal{G}^0 \subset \mathcal{G}^1$, so $\widetilde{a} \in \{\widetilde{a_0},\dots, \widetilde{a_r}\}$, as claimed.

    By \cite{LN24}*{Theorem 1.4} and the above claim, the Markov partition $\{\widetilde{a_0},\dots, \widetilde{a_r}\}$ satisfies conditions \ref{condition:hp}, \ref{condition:uv}, \ref{condition:qs}, as defined in Section \ref{section:extension}.  By Theorem \ref{thm:cmc},  $\{b_0,\dots,b_r\}$ satisfies conditions \ref{condition:hp}, \ref{condition:uv}, \ref{condition:qs} and \ref{condition:qs_strong} with every point in $\{b_0,\dots, b_r\}$ being symmetrically parabolic. Consider the map $H_v=h_v\circ \phi_v^{-1}\colon \mathbb{D}\to D_v$, which is a topological conjugacy between $B_v$ and $\Psi$. By Theorem \ref{theorem:extension_generalization}, $H_v$ extends to a David homeomorphism map from $\mathbb{D}$ onto the disk $D_v$. Since $W_v$ is a quasidisk, by Proposition \ref{prop:david_qc_invariance} (iv), $h_v$ extends to a David map from $W_v$ onto $D_v$, as required in \ref{f:4}.

    If $\mathcal{J} (f)$ and thus $\mathcal J(R)$ is a fat gasket, as in \ref{f:5}, then $W_v$ is a quasidisk by Lemma \ref{lem:tpp}. We can obtain a quasiconformal extension of $H_v$ as follows. By Remark \ref{remark:hyp_par_analytic}, each point in $\{\widetilde{a_0},\dots, \widetilde{a_r}\}$ is either symmetrically hyperbolic or symmetrically parabolic for $B_v$. Since each point in $\{\widetilde{a_0},\dots, \widetilde{a_r}\}$ corresponds to a contact point of two Fatou components, by Lemma \ref{lem:tpp} there is a unique periodic point $\widetilde a\in \{\widetilde{a_0},\dots, \widetilde{a_r}\}$. By the same lemma, this point corresponds to a parabolic contact point $a\in \partial W_v$ with multiplicity $3$, which therefore attracts orbits in $W_v$ (given that $\mathcal J(R)$ is a gasket so $a$ can be on the boundary of at most two Fatou components). We conclude that the point $\widetilde a\in \mathbb S^1$ is symmetrically parabolic. Each other point in $\{\widetilde{a_0},\dots, \widetilde{a_r}\}$ is mapped to $\widetilde a$ with an iterate of $B_v$, which is locally bi-Lipschitz. Hence, each point in $\{\widetilde{a_0},\dots, \widetilde{a_r}\}$ is symmetrically parabolic. Also, as discussed above, each point in $\{b_0,\dots,b_r\}$ is symmetrically parabolic by Theorem \ref{thm:cmc}. By Theorem \ref{theorem:extension_generalization}, the topological conjugacy $H_v\colon  \partial \mathbb{D} \to \partial D_v$ extends to a quasiconformal homeomorphism between the disks $\mathbb{D}$ and $D_v$. Therefore, $h_v$ extends to a quasiconformal homeomorphism from $W_v$ onto $D_v$.

By Lemma \ref{lem:preperiodic}, there exists a homeomorphism $h^1\colon \overline{W^1}\to \overline{D^1}$ such that $h^1=h_v$ on $\overline{W_v}$ for each vertex $v\in \mathcal G^1$ and $\Psi\circ h^1=h^1\circ R$ on $\partial W^1$. Note that the components of $\widehat\mathbb{C} \setminus \overline{W^n}$ (or $\widehat\mathbb{C} \setminus \overline{D^n})$ are in correspondence with the faces of $\mathcal G^n$, $n\geq 0$, and each component is a Jordan region. For each component $U_F$ of $\widehat \mathbb{C}\setminus \overline{W^1}$ and for the corresponding component $V_F$ of $\widehat \mathbb{C}\setminus \overline {D^1}$ we extend $h^1|_{\partial U_F}\colon \partial U_F\to \partial V_F$ arbitrarily to a homeomorphism between $\overline {U_F}$ and $\overline{V_F}$. In this way, $h^1$ is extended to a homeomorphism of $\widehat \mathbb{C}$.

    Now, we define a homeomorphism $h^2$ as follows. Let $F$ be a face of $\mathcal{G}^1$ that is mapped to a face $F'$ of $\mathcal{G}^0$ under the map induced by $R$. Let $U_F$ and $U_{F'}$ be the components of $\widehat\mathbb{C} \setminus \overline{W^1}$ and $\widehat\mathbb{C} \setminus \overline{W^0}$ associated to $F$ and $F'$. Similarly, let $V_F$ and $V_{F'}$ be the corresponding components of $\widehat\mathbb{C} \setminus \overline{D^1}$ and $\widehat\mathbb{C} \setminus \overline{D^0}$. Then $R\colon U_F \to U_{F'}$ and $\Psi\colon V_F \to V_{F'}$ are homeomorphisms. Moreover, we have $h_1(U_{F'}) = V_{F'}$ and $\Psi \circ h_1 = h_1 \circ R$ on $\partial U_F$. We define
    $$
    h^2(z)= \begin{cases}
        h^1(z), & \text{ if } z\in \overline{W^1},\\
        (\Psi|_{V_F})^{-1} \circ h^1 \circ R(z), & \text{ if } z\in U_F, \text{ where $F$ is a face of $\mathcal G^1$}.
    \end{cases}
    $$
    By construction, $h^2$ is a homeomorphism on $\widehat\mathbb{C}$ that sends $W^2$ to $D^2$ and satisfies $\Psi\circ h^2=h^1\circ R$ on $\widehat \mathbb{C}\setminus W^1$.
    Inductively, for each $n\geq 1$ we construct a homeomorphism $h^{n+1}$ that sends $W^{n+1}$ to $D^{n+1}$, satisfies $\Psi \circ h^{n+1}= h^{n}\circ R$ on $\widehat \mathbb{C}\setminus W^n$, and  satisfies $h^{n+1} = h^m$ on $W^m$ if $n+1\geq m$. By Lemma \ref{lemma:gasket_sub} \ref{gs:0} (see also Proposition \ref{prop:diam->0}), the diameter of each component of $\widehat\mathbb{C} \setminus \overline{W^n}$ and $\widehat\mathbb{C} \setminus  \overline{D^n}$ is shrinking to $0$.  Thus, we conclude that $h^n$ converges to some homeomorphism $h\colon \widehat\mathbb{C} \to \widehat\mathbb{C}$ such that 
    \begin{align}\label{h_conj}
        \textrm{$\Psi \circ h=h\circ R$ on $\widehat \mathbb{C} \setminus  W^1$.}
    \end{align}
    By construction, we have $h(\mathcal J(f)) = \Lambda(\mathcal P)$ and $h$ conjugates the dynamics of $R|_{\mathcal J(R)}$ and $\Psi|_{\Lambda(\mathcal P)}$. It remains to verify the last two conditions of the theorem. 


We assume that each Fatou component is a quasidisk. Let $\mu$ be the Beltrami coefficient of $h$ on $\widehat\mathbb{C}\setminus \mathcal J(f)$. Let $V_1,\dots , V_l$ be the collection of Fatou components in Lemma \ref{lemma:bilip_blowup}. By the last part of the lemma, we may also include in this collection all Fatou components associated to vertices in $\mathcal{G}^1$. Let $W_v\in \{V_1,\dots,V_l\}$ be a Fatou component corresponding to a vertex $v$ of $\mathcal G$. If $v$ is a vertex of $\mathcal G^1$, by Lemma \ref{lem:preperiodic} we see that $\mu$ is a David--Beltrami coefficient on $W$. Suppose $v$ is a vertex of $\mathcal G_{n+1}\setminus \mathcal G_n$ for some $n\geq 1$. The disk $D_v$ is contained in an open tile $\Omega_F$ of level $n$ and the map $\Psi^{\circ n}$ is uniformly quasiconformal on $\Omega_F$ by Proposition \ref{prop:qce}. Hence, by \eqref{h_conj} and Proposition \ref{prop:david_qc_invariance} (i) and (iii), we conclude that $\mu$ is also a David--Beltrami coefficient on $W_v$. In particular, $\mu$ is a David--Beltrami coefficient in $\bigcup_{i=1}^l V_l$ and satisfies
\begin{align}\label{surgery:periodic}
    \sum_{j=1}^l \sigma(\{z\in V_j: |\mu(z)|\geq 1-\varepsilon\}) \leq  M e^{-\alpha/\varepsilon}
\end{align}
for some constants $M,\alpha>0$ and for all $\varepsilon \in (0,1)$. 

We now check the David condition on the union of all Fatou components. Let $W\notin \{V_1,\dots,V_l\}$ be a Fatou component and $D$ be the corresponding disk of $\mathcal P$. Note that $W$ and $D$ correspond to a vertex of $\mathcal G^{n+1}\setminus \mathcal G^n$ for some $n\geq 1$. Thus, $D$ is contained in an open tile $\Omega_F$ of level $n$. By Lemma \ref{lemma:bilip_blowup}, there exists a minimal $n(W)\geq 1$ such that $W$ is mapped onto $V_j$ for some $j\in \{1,\dots,l\}$ after $n(W)$ iterations. Let $D_j$ be the corresponding disk of $\mathcal{P}$. By the minimality of $n(W)$, $V_j$ and $D_j$ correspond to a vertex of $\mathcal G^k$ for some $k\geq 1$, thus $n\geq n(W)$. Then by Proposition \ref{prop:qce}, $\Psi^{n(W)}\colon D \to  D_j$ is $K$-quasiconformal for some uniform $K\geq 1$. 


By Remark \ref{remark:composition}, the conjugation relation \eqref{h_conj}, and Lemma \ref{lemma:bilip_blowup}, we have
\begin{align}\label{surgery:area}
  \notag\sigma\left(\{z\in W\colon|\mu(z)|\geq 1-\varepsilon\}\right)&\leq \sigma\left( \{z\in W\colon|\mu_{\Psi^{\circ n(W)}\circ h}(z)|\geq 1-K\varepsilon\}\right)\\
  \notag&=\sigma\left( \{z\in W\colon|\mu_{h\circ R^{\circ n(W)}}(z)|\geq 1-K\varepsilon\}\right)\\
  \notag&=\sigma\left( \{z\in W\colon|\mu_{h}(R^{\circ n(W)}(z))|\geq 1-K\varepsilon\}\right)\\
  &\leq L^2(\operatorname{diam}{W})^2\sigma\left(\{z\in V_j\colon|\mu(z)|\geq 1-K\varepsilon\}\right).  
\end{align}
Since $W$ is a quasidisk with a uniform constant by Corollary \ref{corollary:quasidisks}, we conclude (see \cite{Bonk:uniformization}*{Proposition 4.3}) that there exists a uniform constant $C>0$ such that
\begin{align}\label{surgery:diameter}
  (\operatorname{diam}{W})^2\leq C\sigma\left(W\right).
\end{align}
Therefore, by \eqref{surgery:diameter}, \eqref{surgery:area}, and \eqref{surgery:periodic}, we have
\begin{equation}\notag
\begin{split}
\sigma&\left(\{z\in\widehat{\mathbb C}\colon|\mu(z)|\geq 1-\varepsilon\}\right)\\&=\sum_{W \notin \{V_1,..., V_l\}}\sigma\left(\{z\in{W}\colon|\mu(z)|\geq 1-\varepsilon\}\right)+\sum_{j=1}^l \sigma\left(\{z\in{V_j}\colon|\mu(z)|\geq 1-\varepsilon\}\right)\\
&\leq \left(L^2 C\left(\sum_{W \notin \{V_1,..., V_l\}}\sigma\left(W\right)\right)+1\right)\cdot\left(\sum_{j=1}^l\sigma\left(\{z\in V_j\colon|\mu(z)|\geq 1-K\varepsilon\}\right)\right)\\
&\leq \left(L^2C\sigma\left(\widehat{\mathbb C}\right)+1\right)Me^{-\alpha/(K\varepsilon)}
\end{split}
\end{equation}
for $\varepsilon \in (0,1/K)$. This completes the proof that $\mu$ is a David--Beltrami coefficient. 

In the case that $\mathcal J(R)$ is a fat gasket, then $|\mu|$ is bounded away from $1$ by Lemma \ref{lem:preperiodic} and Proposition \ref{prop:qce}. Thus, we conclude that $h$ is quasiconformal on $\widehat\mathbb{C}\setminus \mathcal J(f)$.

Recall that for $i=1,2$, we denote by $\mathcal{P}_i$ the circle packing for the spherical subdivision graph $\mathcal{G}_i$. By Theorem \ref{thm:QU}, the fat gasket Julia set $\mathcal{J}(R)$ is quasiconformally homeomorphic to a circle packing with tangency graph $\mathcal G_1$. By Theorem \ref{thm:qch}, $\mathcal J(R)$ is quasiconformally homeomorphic to the circle packing $\mathcal{P}_1$. Therefore, in order to prove the theorem, it suffices to construct appropriate quasiconformal maps between $\mathcal{P}_1$ and $\mathcal{P}_2$.  Recall that
    \begin{align*}
        \mathcal{G}_1 &= \mathcal{G}_{1,+} \cup \mathcal{G}_{1,-} = \widetilde{\mathcal{G}}_{1,+} \cup \widetilde{\mathcal{G}}_{1,-} \quad \textrm{and} \quad  \mathcal{G}_2 = \mathcal{G}_{2,+} \cup \mathcal{G}_{2,-},
    \end{align*}
    where each graph $\mathcal{G}_{i, \pm}$ and $\widetilde{\mathcal{G}}_{1,+}$ is isomorphic to the initial subdivision graph $\mathcal{G}$. We now construct open sets $U^\pm$ and maps $\phi^\pm$ associated to $\mathcal{G}_{1,\pm}$ as follows. Let $\mathcal{P}_{i, \pm}$ and $\widetilde{\mathcal{P}}_{1, \pm}$ be the corresponding sub-circle packings of $\mathcal{P}_i$, $i=1,2$. Note these circle packings all have the same combinatorics.  Let $\widehat{U}^\pm$ (resp.\ $V^\pm$) be the Jordan domains bounded by the limit set  of the group generated by reflections along the circles in $\mathcal{P}_1$ (resp.\ $\mathcal{P}_2$) associated to $A, B, C, D$ as illustrated in Figure \ref{fig:FGJ}. By Theorem \ref{thm:existenceTeich}, there exist quasiconformal maps $\widehat{\phi}^\pm\colon (\widehat\mathbb{C}, \widehat{U}^\pm) \to (\widehat\mathbb{C}, V^\pm)$ so that $\widehat{\phi}^\pm(\overline{\widehat{U}^\pm} \cap \Lambda(\mathcal{P}_1)) = \overline{V^\pm} \cap \Lambda(\mathcal{P}_2)$.  By pulling back $\widehat{U}^\pm$ and $\widehat{\phi}^\pm$ under the quasiconformal map between $\mathcal{J}(R)$ and $\Lambda(\mathcal{P}_1)$, we obtain regions $U^\pm$ and maps $\phi^\pm$ that satisfy the desired conclusion. Similarly, we can construct regions $\widetilde{U}^\pm$ and maps $\widetilde{\phi}^\pm$ for $\widetilde{\mathcal{G}}_{1,+}$. By construction we have $\mathcal{J}(R) \subset U^+ \cup U^- \cup \widetilde{U}^+ \cup \widetilde{U}^-$ and the theorem follows.
